parameters.body/body/messageBody:
{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.4",
  "body": [
    {
      "type": "ColumnSet",
      "columns": [
        {
          "type": "Column",
          "width": "auto",
          "items": [
            {
              "type": "Image",
              "url": "https://cdn.jsdelivr.net/gh/microsoft/fluentui-emoji@main/icons/Warning%20Color/Warning%20Color.svg",
              "size": "Medium",
              "altText": "New Incident"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Neuer Incident",
              "weight": "Bolder",
              "size": "Large",
              "color": "Accent"
            },
            {
              "type": "TextBlock",
              "text": "@{triggerOutputs()?['body/Name']}",
              "weight": "Semibold",
              "size": "Medium",
              "wrap": true,
              "spacing": "Small",
              "isSubtle": true
            }
          ]
        }
      ]
    },
    {
      "type": "FactSet",
      "facts": [
        {
          "title": "Ticketnummer",
          "value": "@{triggerOutputs()?['body/Title']}"
        },
        {
          "title": "Priorität",
          "value": "@{triggerOutputs()?['body/Priority/Value']}"
        },
        {
          "title": "Kategorie",
          "value": "@{triggerOutputs()?['body/Category/Value']}"
        },
        {
          "title": "Fachbereich",
          "value": "@{triggerOutputs()?['body/Department/Value']}"
        },
        {
          "title": "Anforderer",
          "value": "@{triggerOutputs()?['body/RequestedBy/DisplayName']}"
        },
        {
          "title": "Erstellt",
          "value": "@{formatDateTime(triggerOutputs()?['body/Created'], 'dd.MM.yyyy HH:mm')}"
        }
      ],
      "spacing": "Medium"
    }
  ],
  "actions": [
    {
      "type": "Action.OpenUrl",
      "title": "Im Portal öffnen",
      "url": "https://apps.powerapps.com/play/e/feb1ba32-a1dc-eb45-be98-d17dd057f440/a/33a1afb1-1ce5-48d0-bc21-2072d2757bb3?tenantId=f7eb5dc9-e7d8-4a6b-b456-7a76589e5aff&ticketId=@{triggerOutputs()?['body/ID']}"
    }
  ]
}
